import {toMono16k,hasSpeechEnergy} from './stt-audio.js';
export function createUrduDictation({document:doc,getLanguage,onUseQuestion,onUseNotes,onStartCapture=()=>{},workerFactory,fetcher=globalThis.fetch,decodeAudio}){
 const win=doc.defaultView,$=id=>doc.getElementById(id);let worker,job=0,models,stream,recorder,recognition,timer,startTime,recording=false,busy=false,canceled=false,pendingMicId=null;
 const text=(ur,en)=>getLanguage()==='ur'?ur:en;function status(ur,en){$('stt-status').textContent=text(ur,en)}
 function controls(){$('stt-transcript').readOnly=busy||recording;const local=$('stt-engine').value==='local';$('stt-model-label').hidden=!local;$('stt-load').hidden=!local;$('stt-file').disabled=!local||busy||recording;$('stt-record').disabled=busy;$('stt-stop').disabled=!recording;$('stt-record').setAttribute('aria-pressed',String(recording));$('stt-load').disabled=busy||recording;for(const id of ['stt-use','stt-notes','stt-copy'])$(id).disabled=!$('stt-transcript').value.trim();}
 function release(){if(timer)win.clearInterval(timer);timer=null;stream?.getTracks().forEach(track=>track.stop());stream=null;recording=false;controls()}
 function cancel(){job++;pendingMicId=null;canceled=true;try{if(recorder?.state==='recording')recorder.stop()}catch{}recognition?.abort?.();release();worker?.terminate?.();worker=null;busy=false;$('stt-progress').hidden=true;controls();status('عمل روک دیا گیا ہے۔ پچھلی تحریر برقرار ہے؛ ضرورت ہو تو دوبارہ اردو بولیں۔','Processing canceled. Existing text is retained; record Urdu again when ready.')}
 async function model(){if(!models){const r=await fetcher('stt-models.json');if(!r.ok)throw Error('Model configuration could not load.');models=await r.json()}return models[$('stt-model').value]}
 function ensureWorker(){if(worker)return worker;const make=workerFactory||(url=>new win.Worker(url,{type:'module'}));worker=make(new URL('./stt-worker.js',import.meta.url));worker.onmessage=e=>{const r=e.data;if(r.id!==job)return;if(r.type==='progress'){const p=r.progress;if(p.status==='progress'){$('stt-progress').hidden=false;$('stt-progress').value=p.progress||0;status(`اردو ماڈل لوڈ ہو رہا ہے: ${Math.round(p.progress||0)}٪ · ${p.file||''}`,`Loading Urdu model: ${Math.round(p.progress||0)}% · ${p.file||''}`)}return}busy=false;$('stt-progress').hidden=true;if(r.type==='transcript'){$('stt-transcript').value=r.text.trim();status(r.text.trim()?'اردو تحریر تیار ہے۔ نام اور اعداد درست کر کے سوال یا نوٹ میں استعمال کریں۔':'واضح الفاظ نہیں ملے۔ خاموشی یا شور میں دوبارہ کوشش کریں۔',r.text.trim()?'Urdu transcript ready. Check names and numbers before using it.':'No clear words were found. Try again with less noise.')}else if(r.type==='ready')status('اردو ماڈل تیار ہے۔ اب ریکارڈ کریں یا آڈیو فائل چنیں۔','Urdu model ready. Record or choose an audio clip.');else if(r.type==='error'){worker?.terminate?.();worker=null;status(`اردو تحریر نہیں بن سکی: ${r.message}۔ دوبارہ کوشش کریں، چھوٹا ماڈل یا براؤزر کا طریقہ چنیں۔`,`Urdu transcription failed: ${r.message}. Retry, use the smaller model or explicitly choose browser recognition.`)}controls()};worker.onerror=()=>{worker?.terminate?.();worker=null;busy=false;controls();status('اردو ماڈل نہیں کھل سکا۔ انٹرنیٹ دیکھیں، دوبارہ کوشش کریں یا براؤزر کا طریقہ چنیں۔','The Urdu model could not load. Check connectivity, retry or explicitly choose browser recognition.')};return worker}
 async function request(type,audio){const id=++job;busy=true;controls();status('اردو پہچانی جا رہی ہے۔ پہلی بار ماڈل لوڈ ہونے میں وقت اور انٹرنیٹ ڈیٹا لگتا ہے۔','Recognising Urdu. Initial model loading needs time and a substantial download.');try{const config=await model();if(id!==job)return;const w=ensureWorker();w.postMessage({id,type,model:config,...(audio?{audio}:{})},audio?[audio.buffer]:[])}catch(e){if(id!==job)return;busy=false;controls();status(`اردو تحریر نہیں بن سکی: ${e.message}`,`Urdu transcription could not start: ${e.message}`)}}
 async function decode(blob){if(blob.size>10*1024*1024)throw Error('Choose an audio file smaller than 10 MB.');if(decodeAudio)return decodeAudio(blob);const Audio=win.AudioContext||win.webkitAudioContext;if(!Audio)throw Error('Audio decoding is unavailable in this browser.');const context=new Audio();try{const buffer=await context.decodeAudioData(await blob.arrayBuffer());const channels=Array.from({length:buffer.numberOfChannels},(_,k)=>buffer.getChannelData(k));return toMono16k(channels,buffer.sampleRate)}finally{await context.close()}}
 async function transcribe(blob){const id=++job;busy=true;controls();try{const audio=await decode(blob);if(id!==job)return;if(!hasSpeechEnergy(audio))throw Error('The clip is silent or too quiet.');await request('transcribe',audio)}catch(e){if(id!==job)return;busy=false;controls();status(`آڈیو نہیں پڑھی جا سکی: ${e.message}`,`Could not read the audio: ${e.message}`)}}
 function browserCapture(){const Recognition=win.SpeechRecognition||win.webkitSpeechRecognition;if(!Recognition){status('اس براؤزر میں اردو آواز پہچاننے کی سروس نہیں۔ مقامی Whisper یا آڈیو فائل کا طریقہ استعمال کریں۔','Browser recognition is unavailable. Choose local Whisper or an audio file.');return}const rid=++job;pendingMicId=rid;let failed=false;const localRecognizer=new Recognition();recognition=localRecognizer;localRecognizer.lang='ur-PK';localRecognizer.continuous=false;localRecognizer.interimResults=true;localRecognizer.maxAlternatives=1;localRecognizer.onstart=()=>{if(rid!==job){localRecognizer.abort?.();return}pendingMicId=null;busy=false;recording=true;controls();status('اردو سن رہا ہے۔ یہ براؤزر کی سروس ہے اور آواز فراہم کنندہ کو بھیجی جا سکتی ہے۔','Listening in Urdu. This is a browser service and audio may be sent to its provider.')};localRecognizer.onresult=e=>{if(rid!==job)return;let result='';for(let k=0;k<e.results.length;k++)result+=e.results[k][0].transcript+' ';$('stt-transcript').value=result.trim();controls()};localRecognizer.onend=()=>{if(rid!==job)return;pendingMicId=null;busy=false;release();if(!failed)status('تحریر دیکھیں اور درست کرنے کے بعد استعمال کریں۔','Review and edit the Urdu transcript before using it.')};localRecognizer.onerror=()=>{if(rid!==job)return;pendingMicId=null;failed=true;release();status('اردو پہچاننے کی سروس یا مائیکروفون دستیاب نہیں۔ مقامی Whisper یا تحریر کا طریقہ استعمال کریں۔','Urdu recognition or microphone access failed. Use local Whisper or type instead.')};busy=true;controls();try{localRecognizer.start()}catch(e){pendingMicId=null;busy=false;release();status(`مائیکروفون نہیں کھلا: ${e.message}`,`Could not start the microphone: ${e.message}`)}}
 async function record(){if(recording||busy)return;onStartCapture();if($('stt-engine').value==='browser'){browserCapture();return}if(!win.navigator.mediaDevices?.getUserMedia||!win.MediaRecorder){status('اس آلے میں ریکارڈنگ دستیاب نہیں۔ آڈیو فائل چنیں یا براؤزر کا طریقہ دیکھیں۔','Recording is unavailable on this device. Choose an audio clip or explicitly select browser recognition.');return}const id=++job;pendingMicId=id;canceled=false;busy=true;controls();try{const audioStream=await win.navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true}});if(id!==job){audioStream.getTracks().forEach(t=>t.stop());return}pendingMicId=null;busy=false;stream=audioStream;const chunks=[];const captureRecorder=new win.MediaRecorder(stream);recorder=captureRecorder;captureRecorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};captureRecorder.onstop=()=>{if(id!==job){audioStream.getTracks().forEach(t=>t.stop());return}release();if(!canceled&&chunks.length)transcribe(new win.Blob(chunks,{type:captureRecorder.mimeType||'audio/webm'}))};captureRecorder.start();recording=true;startTime=Date.now();$('stt-timer').textContent='0:00';controls();status('اردو بولیں۔ ریکارڈنگ روکنے پر اسے اردو تحریر میں بدلا جائے گا۔','Speak Urdu. Stopping the recording starts Urdu transcription.');timer=win.setInterval(()=>{const seconds=Math.floor((Date.now()-startTime)/1000);$('stt-timer').textContent=`0:${String(seconds).padStart(2,'0')}`;if(seconds>=30)recorder.stop()},500)}catch(e){if(id!==job)return;pendingMicId=null;busy=false;release();status(`مائیکروفون کی اجازت یا ریکارڈنگ نہیں ملی: ${e.message}`,`Microphone permission or recording failed: ${e.message}`)}}
 $('stt-record').onclick=record;$('stt-stop').onclick=()=>{if($('stt-engine').value==='browser')recognition?.stop();else if(recorder?.state==='recording')recorder.stop()};$('stt-load').onclick=()=>request('load');$('stt-cancel').onclick=cancel;$('stt-file').onchange=()=>{const file=$('stt-file').files?.[0];if(file)transcribe(file)};
 for(const id of ['stt-engine','stt-model'])$(id).onchange=()=>{cancel();controls()};$('stt-transcript').oninput=controls;
 $('stt-use').onclick=()=>{const value=$('stt-transcript').value.trim();if(value)onUseQuestion(value)};
 $('stt-notes').onclick=()=>{const value=$('stt-transcript').value.trim();if(value)onUseNotes(value)};
 $('stt-copy').onclick=async()=>{try{await win.navigator.clipboard.writeText($('stt-transcript').value);status('اردو تحریر نقل ہو گئی ہے۔','Urdu transcript copied.')}catch{status('نقل کی اجازت نہیں ملی۔ تحریر منتخب کر کے دستی طور پر نقل کریں۔','Clipboard permission unavailable. Select and copy the transcript manually.')}};
 doc.addEventListener('visibilitychange',()=>{if(doc.hidden&&(recording||pendingMicId!==null))cancel()});win.addEventListener('hashchange',()=>{if(win.location.hash!=='#planner'&&(recording||pendingMicId!==null))cancel()});controls();
 return {focus(){doc.getElementById('urdu-dictation').scrollIntoView?.({block:'start'});$('stt-transcript').focus()},destroy(){cancel()}};
}
